import{_ as o,o as s,c as t,ae as n}from"./chunks/framework.Dn7Y7LSn.js";const l=JSON.parse('{"title":"Interview Questions: PHP Basics","description":"","frontmatter":{},"headers":[],"relativePath":"module-1/interview-questions.md","filePath":"module-1/interview-questions.md"}'),r={name:"module-1/interview-questions.md"};function i(a,e,c,d,p,g){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="interview-questions-php-basics" tabindex="-1">Interview Questions: PHP Basics <a class="header-anchor" href="#interview-questions-php-basics" aria-label="Permalink to &quot;Interview Questions: PHP Basics&quot;">​</a></h1><p><strong>Q1: নিচের কোনটি পিএইচপির ডাটাটাইপ নয়?</strong><em>Integer, Object, NULL, Number</em><strong>Ans:</strong> Number (পিএইচপিতে <code>Integer</code> এবং <code>Float</code> আছে, কিন্তু <code>Number</code> নামে আলাদা কোনো টাইপ নেই)।</p><p><strong>Q2: নিচের কোডটি চালালে আউটপুট কী হবে?</strong></p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;10+10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><strong>Ans:</strong> <code>10+10</code> (যেহেতু এটি স্ট্রিং)।</p><p><strong>Q3: What is the difference between <code>gettype</code> and <code>var_dump</code>?</strong><strong>Ans:</strong> <code>gettype</code> শুধুমাত্র ডাটার টাইপ রিটার্ন করে, কিন্তু <code>var_dump</code> টাইপ এবং ভ্যালু উভয়ই রিটার্ন করে।</p><p><strong>Q4: PHP তে <code>null</code> এবং খালি স্ট্রিং <code>&quot;&quot;</code> এর মধ্যে পার্থক্য কী?</strong><strong>Ans:</strong> <code>null</code> হলো একটি স্পেশাল টাইপ যা বোঝায় ভেরিয়েবলটির কোনো মান নেই। <code>&quot;&quot;</code> হলো একটি খালি স্ট্রিং যার মান আছে কিন্তু সেটি ফাঁকা।</p><p><strong>Q5: PHP তে অ্যারে তৈরির পদ্ধতি কী?</strong><strong>Ans:</strong> <code>array()</code> ফাংশন দিয়ে অথবা <code>[]</code> শর্টকাট দিয়ে।</p><p><strong>Q6: অ্যারে কি <code>echo</code> দিয়ে প্রিন্ট করা যায়?</strong><strong>Ans:</strong> না, <code>echo</code> শুধুমাত্র স্ট্রিং প্রিন্ট করতে পারে। অ্যারে দেখতে <code>print_r()</code> বা <code>var_dump()</code> ব্যবহার করা হয়।</p><p><strong>Q7: PHP তে ভিন্ন ভিন্ন টাইপের ডাটা একই অ্যারেতে রাখা যায়?</strong><strong>Ans:</strong> হ্যাঁ, পিএইচপি অ্যারে হেটারোজিনিয়াস (Heterogeneous)।</p>',10)])])}const h=o(r,[["render",i]]);export{l as __pageData,h as default};
